def parse_csv(csv_content):
    csv_dict = defaultdict(dict)
    for index, line in enumerate(csv_content.splitlines()):
        if index == 0:
            headers = line.split(',')
            continue
        values = line.split(',')
        for item_index, item in enumerate(values):
            csv_dict[headers[item_index]][index] = item
    return csv_dict

