import shutil
def extract_all(tar_file):
    tar = tarfile.open(tar_file)
    for tar_file in tar.getmembers():
        if tar_file.name.endswith('/'):
            tar.extractall(tar_file.name + '/../', tar_file)
        else:
            dest_dir = "/".join(tar_file.name.split('/')[:-1])
            if not os.path.exists(dest_dir):
                os.makedirs(dest_dir)
            tarball = tar.extractfile(tar_file)
            shutil.copyfileobj(tarball, open(os.path.join(dest_dir, tar_file.name), 'wb'))
            tarball.close()
    tar.close()

