import jax.numpy as jnp

def cross_entropy(probabilities, true_labels):
    batch_size = probabilities.shape[0]
    loss = -jnp.mean(jnp.sum(true_labels * jnp.log(probabilities), axis=1))
    return loss

def softmax(logits):
    exp_logits = jnp.exp(logits - jnp.max(logits, axis=-1, keepdims=True))
    return exp_logits / jnp.sum(exp_logits, axis=-1, keepdims=True)

def main():
    model_vars = {
        'weights': (2, 5),
        'bias': (5,)
    }

    def loss_fn(parameters, batch):
        weights, bias = parameters

        logits = jnp.dot(batch, weights) + jnp.expand_dims(bias, 0)
        probabilities = softmax(logits)
        return cross_entropy(probabilities, batch)

    opt_state = jax.optimizers.adam(5e-3).init(model_vars)
    opt_update, opt_init = jax.optimizers.get_updates(loss_fn)

    model_params = opt_init(opt_state)

