from flake8.plugins import import_error
import flake8
import sys

def __init__(self, tree, filename):
    self.tree = tree
    self.filename = filename
    self.import_errors = []

def run(self):
    from importlib.abc import Loader
    for line, node in self.tree:
        if isinstance(node, importlib.ast.ImportError):
            self.import_errors.append((line, f"Can't import '{node.name}' from '{self.filename}': {node.exception} (at line {line})"))
    return 0 if not self.import_errors else 1

def report(self, reporter, error):
    if error in self.import_errors:
        reporter.info(error[1], line_number=error[0])

if __name__ == "__main__":
    sys.exit(flake8.main([
        "--select", str(import_error),
    ]))

