import requests
from bs4 import BeautifulSoup
import re

def scrape_for_divorce_reason():
    url = 'https://www.divorcemag.com/whats-my-reason-for-divorce'
    response = requests.get(url)
    html = response.text

    soup = BeautifulSoup(html, 'html.parser')

    reason = soup.find('div', {'id': 'reason'}).text
    if is_reason_valid(reason):
        print(f"Divorce reason: {reason}")
    else:
        print("Divorce invalid, please rethink.")

def is_reason_valid(reason):
    bad_reasons = ['my wife','my husband','my ex','wife']

    for bad in bad_reasons:
        if re.search(bad, reason):
            return False

    return True

scrape_for_divorce_reason()
